from __future__ import annotations

import base64
import csv
import io
import os
from pathlib import Path
from typing import Any

import psycopg2
from psycopg2.extras import RealDictCursor

from nicegui import ui

BASE_DIR = Path(__file__).resolve().parent
DATABASE_URL = os.getenv("DATABASE_URL")
if not DATABASE_URL:
    raise RuntimeError("A variável DATABASE_URL não foi configurada no Render.")


def get_connection():
    return psycopg2.connect(DATABASE_URL)


def initialize_database() -> None:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                CREATE TABLE IF NOT EXISTS processos (
                    id BIGSERIAL PRIMARY KEY,
                    pasta TEXT NOT NULL DEFAULT '',
                    nome TEXT NOT NULL DEFAULT '',
                    numero TEXT NOT NULL DEFAULT '',
                    assunto TEXT NOT NULL DEFAULT '',
                    link TEXT NOT NULL DEFAULT ''
                )
                """
            )
            cursor.execute("SELECT COUNT(*) FROM processos")
            total = cursor.fetchone()[0]
            if total == 0:
                import_embedded_data(connection)
        connection.commit()


def import_file(path: Path, connection) -> int:
    """Importa um TSV, incluindo campos multilinha entre aspas."""
    inserted = 0
    with path.open("r", encoding="utf-8-sig", newline="") as file:
        reader = csv.reader(file, delimiter="\t", quotechar='"')
        next(reader, None)
        with connection.cursor() as cursor:
            for row in reader:
                if not row or not any(cell.strip() for cell in row):
                    continue
                values = (row + [""] * 5)[:5]
                cursor.execute(
                    "INSERT INTO processos (pasta, nome, numero, assunto, link) VALUES (%s, %s, %s, %s, %s)",
                    tuple(value.strip() for value in values),
                )
                inserted += 1
    connection.commit()
    return inserted


# Base completa incorporada neste arquivo: 220,577 bytes / todos os processos anexados.
EMBEDDED_TSV = base64.b64decode(
    ""
).decode("utf-8-sig")


def import_embedded_data(connection) -> int:
    """Importa a base completa incorporada no próprio main.py."""
    inserted = 0
    reader = csv.reader(io.StringIO(EMBEDDED_TSV), delimiter="\t", quotechar='"')
    next(reader, None)
    with connection.cursor() as cursor:
        for row in reader:
            if not row or not any(cell.strip() for cell in row):
                continue
            values = (row + [""] * 5)[:5]
            cursor.execute(
                "INSERT INTO processos (pasta, nome, numero, assunto, link) VALUES (%s, %s, %s, %s, %s)",
                tuple(value.strip() for value in values),
            )
            inserted += 1
    connection.commit()
    return inserted


def list_processes(search: str = "") -> list[dict[str, Any]]:
    search = search.strip()
    with get_connection() as connection:
        with connection.cursor(cursor_factory=RealDictCursor) as cursor:
            if search:
                pattern = f"%{search}%"
                cursor.execute(
                    """
                    SELECT id, pasta, nome, numero, assunto, link
                    FROM processos
                    WHERE pasta ILIKE %s OR nome ILIKE %s OR numero ILIKE %s OR assunto ILIKE %s OR link ILIKE %s
                    ORDER BY id
                    """,
                    (pattern, pattern, pattern, pattern, pattern),
                )
            else:
                cursor.execute(
                    """
                    SELECT id, pasta, nome, numero, assunto, link
                    FROM processos
                    ORDER BY id
                    """
                )
            return [dict(row) for row in cursor.fetchall()]


def save_process(data: dict[str, str], process_id: int | None = None) -> None:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            if process_id is None:
                cursor.execute(
                    "INSERT INTO processos (pasta, nome, numero, assunto, link) VALUES (%s, %s, %s, %s, %s)",
                    (data["pasta"], data["nome"], data["numero"], data["assunto"], data["link"]),
                )
            else:
                cursor.execute(
                    """
                    UPDATE processos
                    SET pasta = %s, nome = %s, numero = %s, assunto = %s, link = %s
                    WHERE id = %s
                    """,
                    (data["pasta"], data["nome"], data["numero"], data["assunto"], data["link"], process_id),
                )
        connection.commit()


def delete_process(process_id: int) -> None:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute("DELETE FROM processos WHERE id = %s", (process_id,))
        connection.commit()


initialize_database()

columns = [
    {"name": "pasta", "label": "Pasta", "field": "pasta", "align": "left", "sortable": True},
    {"name": "nome", "label": "Nome", "field": "nome", "align": "left", "sortable": True},
    {"name": "numero", "label": "Nº do processo", "field": "numero", "align": "left"},
    {"name": "assunto", "label": "Assunto", "field": "assunto", "align": "left"},
    {"name": "link", "label": "Documento", "field": "link", "align": "left"},
]


@ui.page("/")
def main_page() -> None:
    search_input: ui.input
    process_table: ui.table
    dialog: ui.dialog
    form_fields: dict[str, ui.input | ui.textarea] = {}
    current_id: int | None = None

    def refresh_table() -> None:
        process_table.rows = list_processes(search_input.value or "")
        process_table.update()
        total_label.set_text(f"{len(process_table.rows)} processo(s) exibido(s)")

    def close_dialog() -> None:
        dialog.close()

    def form_data() -> dict[str, str]:
        return {name: str(field.value or "").strip() for name, field in form_fields.items()}

    def persist_form() -> None:
        data = form_data()
        if not data["nome"] and not data["numero"]:
            ui.notify("Informe ao menos o nome ou o número do processo.", type="warning")
            return
        save_process(data, current_id)
        close_dialog()
        refresh_table()
        ui.notify("Processo salvo com sucesso.", type="positive")

    def confirm_delete() -> None:
        if current_id is None:
            return
        with ui.dialog() as confirm:
            with ui.card().classes("w-96"):
                ui.label("Excluir processo?").classes("text-h6")
                ui.label("Esta ação não poderá ser desfeita.").classes("text-gray-600")
                with ui.row().classes("w-full justify-end gap-2 mt-4"):
                    ui.button("Cancelar", on_click=confirm.close).props("flat")
                    ui.button(
                        "Excluir",
                        color="negative",
                        on_click=lambda: (delete_process(current_id), confirm.close(), close_dialog(), refresh_table(), ui.notify("Processo excluído.", type="positive")),
                    )
        confirm.open()

    def open_form(process: dict[str, Any] | None = None) -> None:
        nonlocal current_id
        current_id = process["id"] if process else None
        dialog.clear()
        with dialog, ui.card().classes("w-full max-w-3xl"):
            ui.label("Editar processo" if process else "Adicionar processo").classes("text-h5")
            ui.label("Preencha os dados abaixo. O link pode ser do Google Drive ou de outro documento.").classes("text-gray-600 mb-2")
            with ui.column().classes("w-full gap-2"):
                form_fields["pasta"] = ui.input("Pasta", value=str(process.get("pasta", "") if process else "")).props("outlined dense")
                form_fields["nome"] = ui.input("Nome / interessado", value=str(process.get("nome", "") if process else "")).props("outlined dense")
                form_fields["numero"] = ui.textarea("Nº do processo", value=str(process.get("numero", "") if process else "")).props("outlined autogrow")
                form_fields["assunto"] = ui.textarea("Assunto", value=str(process.get("assunto", "") if process else "")).props("outlined autogrow")
                form_fields["link"] = ui.input("Link do processo digitalizado", value=str(process.get("link", "") if process else "")).props("outlined dense")
            with ui.row().classes("w-full justify-between mt-4"):
                if process:
                    ui.button("Excluir", icon="delete", color="negative", on_click=confirm_delete).props("outline")
                else:
                    ui.element("div")
                with ui.row().classes("gap-2"):
                    ui.button("Cancelar", on_click=close_dialog).props("flat")
                    ui.button("Salvar", icon="save", color="primary", on_click=persist_form)
        dialog.open()

    def handle_double_click(event: Any) -> None:
        args = event.args
        row = None
        if isinstance(args, dict):
            row = args.get("row") or args
        elif isinstance(args, list):
            for item in args:
                if isinstance(item, dict) and ("id" in item or "row" in item):
                    row = item.get("row", item)
                    break
        if row and row.get("id") is not None:
            open_form(next((item for item in process_table.rows if item["id"] == row["id"]), None))

    ui.add_head_html(
        """
        <style>
            body { background: #f5f7fb; }
            .q-table th { font-weight: 700; background: #eef2f7; }
            .q-table tbody tr { cursor: pointer; }
            .q-table tbody tr:hover { background: #eaf2ff !important; }
        </style>
        """
    )
    with ui.header().classes("items-center justify-between bg-blue-900 px-6"):
        ui.label("Cadastro de Processos").classes("text-h5 text-white font-bold")
        ui.label("NiceGUI + SQLite").classes("text-blue-100")

    with ui.column().classes("w-full max-w-screen-2xl mx-auto p-6 gap-4"):
        with ui.card().classes("w-full"):
            with ui.row().classes("w-full items-end gap-3"):
                search_input = ui.input("Buscar por pasta, nome, número, assunto ou link").props("outlined clearable").classes("flex-1")
                ui.button("Buscar", icon="search", on_click=refresh_table).classes("h-14")
                ui.button("Adicionar processo", icon="add", color="primary", on_click=lambda: open_form()).classes("h-14")
            search_input.on("keydown.enter", refresh_table)
        with ui.row().classes("w-full items-center justify-between"):
            total_label = ui.label()
            ui.label("Dica: dê duplo clique em uma linha para editar ou excluir.").classes("text-gray-600")
        process_table = ui.table(columns=columns, rows=list_processes(), row_key="id", pagination={"rowsPerPage": 25}).classes("w-full")
        process_table.add_slot(
            "body-cell-link",
            """
            <q-td :props="props">
                <a v-if="props.value" :href="props.value" target="_blank" rel="noopener" class="text-blue-700 underline">Abrir documento</a>
                <span v-else class="text-gray-400">Sem link</span>
            </q-td>
            """,
        )
        process_table.on("rowDblclick", handle_double_click)
        total_label.set_text(f"{len(process_table.rows)} processo(s) exibido(s)")

    dialog = ui.dialog()


ui.run(title="Cadastro de Processos", host="0.0.0.0", port=int(os.getenv("PORT", "8080")), reload=False)
